use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Holder\TenantConfigRegisterdEmailAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigRegisterdEmailAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantConfigRegisterdEmailAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getRegisterdEmail returns null on a freshly created holder.
     */
    public function testRegisterdEmailNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigRegisterdEmailAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isRegisterdEmailAssigned());
        $this->assertNull($holder->getRegisterdEmail());
    }
}
class ImplWithTenantConfigRegisterdEmailAttributeHolderUnitTest
{
    use TenantConfigRegisterdEmailAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedRegisterdEmailRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultRegisterdEmail();
    }
}
